import{_ as r,a0 as o,w as u,s,I as t,x as a,a1 as p,A as i,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"動態壁紙給linux發行版添加活力背景 | LCTT x X-CMD","titleTemplate":false,"description":"動態壁紙給linux發行版添加活力背景 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"動態壁紙給linux發行版添加活力背景 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"動態壁紙給linux發行版添加活力背景 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150527 Animated Wallpaper Adds Live Backgrounds To Linux Distros","title":"動態壁紙給linux發行版添加活力背景","tag":"201507","desc":""},"relativePath":"201507/20150527 Animated Wallpaper Adds Live Backgrounds To Linux Distros.md","filePath":"[post].md"}'),d={name:"201507/20150527 Animated Wallpaper Adds Live Backgrounds To Linux Distros.md"};function m(g,l,x,b,w,f){const e=o("Link");return u(),s("div",null,[l[19]||(l[19]=t("h1",{id:"動態壁紙給linux發行版添加活力背景",tabindex:"-1"},[a("動態壁紙給linux發行版添加活力背景 "),t("a",{class:"header-anchor",href:"#動態壁紙給linux發行版添加活力背景","aria-label":"Permalink to “動態壁紙給linux發行版添加活力背景”"},"​")],-1)),l[20]||(l[20]=t("p",null,[t("strong",null,"我們知道你想擁有一個有格調的ubuntu桌面來炫耀一下 ：）")],-1)),l[21]||(l[21]=t("p",null,[t("img",{src:"http://i.imgur.com/9JIUw5p.gif",alt:"Live Wallpaper"})],-1)),l[22]||(l[22]=t("p",null,[t("em",null,"Live Wallpaper")],-1)),t("p",null,[l[1]||(l[1]=a("在linxu上費一點點勁搭建一個出色的工作環境是很簡單的。今天，我們（",-1)),p(e,{href:"http://www.omgubuntu.co.uk/2011/11/5-system-monitoring-tools-for-ubuntu"},{default:i(()=>[...l[0]||(l[0]=[a("重新",-1)])]),_:1}),l[2]||(l[2]=a("）着重來探討長駐你腦海中那些東西 ：一款自由，開源，能夠給你的截圖增添光彩的工具。",-1))]),l[23]||(l[23]=n('<p>它叫 <strong>Live Wallpaper</strong> (正如你猜的那樣) ，它用由OpenGL驅動的一款動態桌面背景來代替標準的靜態桌面背景。</p><p>最好的一點是：在ubuntu上安裝它很容易。</p><h3 id="動態壁紙主題" tabindex="-1">動態壁紙主題 <a class="header-anchor" href="#動態壁紙主題" aria-label="Permalink to “動態壁紙主題”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/animated-wallpaper-ubuntu-750x383.jpg" alt=""></p><p>Live Wallpaper 不是此類軟件唯一的一款，但它是最好的一款之一。</p><p>它附帶很多不同的開箱即用的主題。</p><p>從精細的(‘noise’)到狂熱的 (‘nexus’)，包羅萬象，甚至有受到Ubuntu Phone歡迎屏幕啓發的obligatory鎖屏壁紙。</p><ul><li>Circles — 帶着‘evolving circle’風格的時鐘，靈感來自於Ubuntu Phone</li><li>Galaxy — 支持自定義大小，位置的旋轉星系</li><li>Gradient Clock — 放在傾斜面上的polar時鐘</li><li>Nexus — 亮色粒子火花穿越屏幕</li><li>Noise — 類似於iOS動態壁紙的Bokeh設計</li><li>Photoslide — 由文件夾（默認為 ~/Photos）內照片構成的動態網格相冊</li></ul><p>Live Wallpaper <strong>完全開源</strong>，所以沒有什麼能夠阻擋天馬行空的藝術家們用訣竅（當然還有耐心）來創造他們自己的精美主題。</p><h3 id="設置-特點" tabindex="-1">設置 &amp; 特點 <a class="header-anchor" href="#設置-特點" aria-label="Permalink to “設置 &amp; 特點”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/live-wallpaper-gui-settings.jpg" alt=""></p><p>雖然某些主題與其它主題相比有更多的選項，但每款主題都可以通過某些方式來配置或者定製。</p><p>例如，Nexus主題中 (上圖所示) 你可以更改脈衝粒子的數量，顏色，大小和出現頻率。</p><p>首選項提供了 <strong>通用選項</strong> 適用於所有主題，包括:</p><ul><li>設置登錄界面的動態壁紙</li><li>自定義動畫背景</li><li>調節 FPS (包括在屏幕上顯示FPS)</li><li>指定多顯示器的行為</li></ul><p>有如此多的選項，diy適用於你自己的桌面背景是很容易的。</p><h3 id="缺陷" tabindex="-1">缺陷 <a class="header-anchor" href="#缺陷" aria-label="Permalink to “缺陷”">​</a></h3><h4 id="沒有桌面圖標" tabindex="-1">沒有桌面圖標 <a class="header-anchor" href="#沒有桌面圖標" aria-label="Permalink to “沒有桌面圖標”">​</a></h4><p>Live Wallpaper在運行時，你無法在桌面添加，打開或者是編輯文件和文件夾。</p><p>首選項程序提供了一個選項來讓你這樣做（只是猜測）。也許是它只能在老版本中使用，在我們的測試中－測試環境為Ununtu 14.10，它不工作。但在測試中發現當把桌面壁紙設置成格式為png的圖片文件時，這個選項有用，不需要是透明的png圖片文件，只要是png圖片文件就行了。</p><h4 id="資源佔用" tabindex="-1">資源佔用 <a class="header-anchor" href="#資源佔用" aria-label="Permalink to “資源佔用”">​</a></h4><p>動態壁紙與標準的壁紙相比要消耗更多的系統資源。</p>',22)),t("p",null,[l[4]||(l[4]=a("我們並不是説任何時候都會消耗大量資源，但至少在我們的測試中是這樣，所以低配置機器和筆記本用户要謹慎使用這款軟件。可以使用 ",-1)),p(e,{href:"http://www.omgubuntu.co.uk/2011/11/5-system-monitoring-tools-for-ubuntu"},{default:i(()=>[...l[3]||(l[3]=[a("系統監視器",-1)])]),_:1}),l[5]||(l[5]=a(" 來追蹤CPU 和GPU的負載。",-1))]),l[24]||(l[24]=n(`<h4 id="退出程序" tabindex="-1">退出程序 <a class="header-anchor" href="#退出程序" aria-label="Permalink to “退出程序”">​</a></h4><p>對我來説最大的“bug”絕對是沒有“退出”選項。</p><p>當然，動態壁紙可以通過托盤圖標和首選項完全退出，那退出托盤圖標呢？沒辦法。只能在終端執行命令‘pkill livewallpaper’。</p><h3 id="怎麼在-ubuntu-14-04-lts-上安裝-live-wallpaper" tabindex="-1">怎麼在 Ubuntu 14.04 LTS+ 上安裝 Live Wallpaper <a class="header-anchor" href="#怎麼在-ubuntu-14-04-lts-上安裝-live-wallpaper" aria-label="Permalink to “怎麼在 Ubuntu 14.04 LTS+ 上安裝 Live Wallpaper”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/terminal-command-750x146.jpg" alt=""></p><p>要想在Ubuntu 14.04 LTS 和更高版本中安裝 Live Wallpaper，你首先需要把官方PPA添加進你的軟件源。 最快的方法是在終端中執行下列命令:</p><pre><code>sudo add-apt-repository ppa:fyrmir/livewallpaper-daily

sudo apt-get update &amp;&amp; sudo apt-get install livewallpaper
</code></pre><p>你還需要安裝 indicator applet，這樣可以方便快速的打開或是關閉動態壁紙，從菜單選擇主題，另外圖形配置工具可以讓你基於你自己的口味來配置每款主題。</p><pre><code>sudo apt-get install livewallpaper-config livewallpaper-indicator
</code></pre><p>所有都安裝好之後你就可以通過Unity Dash來啓動它和它的首選項工具了。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/live-wallpaper-app-launcher.png" alt=""></p><p>讓人不爽的是，安裝完成後，程序不會自動打開托盤圖標，而僅僅將它自己加入自動啓動項，所以，快速來個註銷 -&gt; 登陸它就會出現啦。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如果你正處在無聊呆板的桌面中，幻想有一個更有活力的生活，不妨試試。另外，告訴我們你想看到什麼樣的動態壁紙！</p><hr>`,15)),t("p",null,[l[7]||(l[7]=a("via: ",-1)),p(e,{href:"http://www.omgubuntu.co.uk/2015/05/animated-wallpaper-adds-live-backgrounds-to-linux-distros"},{default:i(()=>[...l[6]||(l[6]=[a("http://www.omgubuntu.co.uk/2015/05/animated-wallpaper-adds-live-backgrounds-to-linux-distros",-1)])]),_:1})]),t("p",null,[l[11]||(l[11]=a("作者：",-1)),p(e,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:i(()=>[...l[8]||(l[8]=[a("Joey-Elijah Sneddon",-1)])]),_:1}),l[12]||(l[12]=a(" 譯者：",-1)),p(e,{href:"https://github.com/Love-xuan"},{default:i(()=>[...l[9]||(l[9]=[a("Love-xuan",-1)])]),_:1}),l[13]||(l[13]=a(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...l[10]||(l[10]=[a("wxy",-1)])]),_:1})]),t("p",null,[l[16]||(l[16]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...l[14]||(l[14]=[a("LCTT",-1)])]),_:1}),l[17]||(l[17]=a(" 原創翻譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...l[15]||(l[15]=[a("Linux中國",-1)])]),_:1}),l[18]||(l[18]=a(" 榮譽推出",-1))])])}const v=r(d,[["render",m]]);export{L as __pageData,v as default};
